{
  "selections": [
    {
      "trait_id": "/core_belief/schema_definition",
      "background_ids": ["/situations/2"],
      "relevance": "내담자가 '다들 자기 자리 찾아가는 것 같은데 저는 그냥 여기 그대로인 것 같다'고 말한 것은 또래에 비해 자신이 실패했다는 확신이 그대로 드러난 발화이며, 동기 단톡방에서 취업 소식을 접한 상황 사례와 직접 연결됨."
    },
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/situations/2"],
      "relevance": "'만약 만나면 요즘 뭐 하냐고 물어볼 텐데 할 말이 없잖아요'라는 발화는 '나는 남들만큼 해내지 못하고 결국 실패할 것이다'라는 핵심 신념이 대인관계 장면에 투사된 것이며, 동기 모임에 나가지 않은 상황 사례와 일치함."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/situations/2"],
      "relevance": "내담자가 동기 단톡방 알림을 꺼버린 행동은 '남과 비교당하는 상황은 최대한 미루거나 피해야 한다'는 규칙에 따른 것이며, 상담사가 '할 말이 없다'는 느낌을 탐색하는 것은 이 규칙이 작동하는 장면을 구체화하려는 시도임."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_positive",
      "background_ids": ["/situations/2"],
      "relevance": "'할 말이 없다'는 것은 실제로 만나면 '진짜 실력'이 드러날까 두려워하는 심리를 반영하며, '전력을 다하지 않으면 실패해도 진짜 실력이 아니었다고 여길 수 있다'는 가정과 연결됨. 동기 모임에 나가지 않은 사례가 이를 뒷받침함."
    },
    {
      "trait_id": "/coping_strategies/2",
      "background_ids": ["/situations/2"],
      "relevance": "내담자가 동기 단톡방 알림을 끄고, '요즘 뭐 하냐'는 질문 자체가 두렵다고 말한 것은 또래·동기들과의 연락과 모임을 끊어 비교 상황을 차단하는 전략과 정확히 일치함."
    },
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data", "/situations/2"],
      "relevance": "동기들과의 비교에서 느끼는 '할 말이 없다'는 무력감은 어릴 적 형과 비교당하며 형성된 '실패' 도식(스키마)이 성인기 또래 관계에서 재현된 것이며, childhood_data에서 그 기원을 확인할 수 있음."
    }
  ]
}

